    if op == "save_margins":
        return save_margins(f.name, f.margins, f.default_margin)
    frappe.throw(fmt("Unknown pricing action: {0}", [op]))


op = form.get("op")
if op in DOC_OPS:
    target = form.get("doc")
    if target is None or isinstance(target, (str, bytes, dict, list)):
        frappe.throw(_("Not permitted"))
    DOC_OPS[op](target)
else:
    frappe.flags.result = run(op, form)

# Eye CRM billing: one Billing Request per invoice, drawn from the deal's Sales Order.
#
#   desk:        frappe.call({method: "eye.billing", args: {op: "so_lines", opportunity: ...}})
#                -> r.message.result
#   doc events:  frappe.call("eye.billing", op="br_validate", doc=doc)
#
# Stages: To be invoiced -> Finance, please issue -> Invoiced -> Collected.
# Sales requests and sends to Finance; Finance (Accounts) marks Invoiced and Collected, by hand
# in Manual mode, or eye.books does it from Zoho Books.

TO_INVOICE = "To be invoiced"
TO_FINANCE = "Finance, please issue"
INVOICED = "Invoiced"
COLLECTED = "Collected"
STAGES = [TO_INVOICE, TO_FINANCE, INVOICED, COLLECTED]
DONE = [INVOICED, COLLECTED]
APPROVED_STAGE = "Quote approved"
ACCOUNTS_ROLES = ["Accounts User", "Accounts Manager"]

flt = frappe.utils.flt
form = frappe.form_dict


# ---------------------------------------------------------------- helpers

def fmt(msg, values):
    out = _(msg)
    for i, v in enumerate(values):
        out = out.replace("{" + str(i) + "}", str(v))
    return out


def text(v):
    return " ".join(str(v or "").split())


def money(v, currency):
    return frappe.utils.fmt_money(flt(v), currency=currency)


def has_role(role):
    user = frappe.session.user
    if user == "Administrator":
        return True
    return bool(frappe.db.exists("Has Role", {"parent": user, "parenttype": "User", "role": role}))


def is_system():
    # each Server Script has its own frappe.flags, so another script can't vouch for a call:
    # automatic answers run as Administrator (the scheduler) and pass the role checks instead
    return False


def is_finance():
    return is_system() or has_role("System Manager") or any([has_role(r) for r in ACCOUNTS_ROLES])


def finance_users():
    users = set(frappe.get_all("Has Role", filters={"role": ["in", ACCOUNTS_ROLES], "parenttype": "User"}, pluck="parent"))
    return [u for u in users if u not in ("Administrator", "Guest") and frappe.db.get_value("User", u, "enabled")]


def notify(user, doctype, name, subject, kind="Alert"):
    if not user or user == frappe.session.user:
        return
    frappe.get_doc({"doctype": "Notification Log", "for_user": user, "type": kind, "document_type": doctype,
                    "document_name": name, "subject": subject, "from_user": frappe.session.user}).insert(ignore_permissions=True)


def assign(doctype, name, users, description, date=None):
    for user in set([u for u in users if u]):
        if frappe.db.exists("ToDo", {"allocated_to": user, "reference_type": doctype, "reference_name": name, "status": "Open"}):
            continue
        frappe.get_doc({"doctype": "ToDo", "allocated_to": user, "reference_type": doctype, "reference_name": name,
                        "description": description, "date": date, "assigned_by": frappe.session.user}).insert(ignore_permissions=True)
        notify(user, doctype, name, description, "Assignment")


def close_todos(doctype, name):
    for t in frappe.get_all("ToDo", filters={"reference_type": doctype, "reference_name": name, "status": "Open"}, pluck="name"):
        todo = frappe.get_doc("ToDo", t)
        todo.status = "Closed"
        todo.save(ignore_permissions=True)


def billed_qty(so_detail, exclude=None):
    """Qty of a Sales Order line already in Billing Requests."""
    filters = {"so_detail": so_detail, "parenttype": "Billing Request"}
    if exclude:
        filters["parent"] = ["!=", exclude]
    return sum([flt(r.qty) for r in frappe.get_all("Billing Request Item", filters=filters, fields=["qty"])])


def get_br(name, ptype="read"):
    br = frappe.get_doc("Billing Request", name)
    br.check_permission(ptype)
    return br


# ---------------------------------------------------------------- requesting an invoice

def so_lines(opportunity):
    """The deal's Sales Order lines and what is left to bill on each."""
    opp = frappe.get_doc("Opportunity", opportunity)
    opp.check_permission("read")
    if not opp.custom_sales_order:
        frappe.throw(_("The deal has no Sales Order yet: it is made when Accounts approve the project"))
    so = frappe.get_doc("Sales Order", opp.custom_sales_order)
    rows = []
    for i in so.items:
        left = flt(i.qty) - billed_qty(i.name)
        rows.append({"so_detail": i.name, "item_code": i.item_code, "item_name": i.item_name,
                     "description": frappe.utils.strip_html(i.description or "")[:140],
                     "service_type": i.get("custom_service_type"), "qty": flt(i.qty), "left": left, "rate": flt(i.rate)})
    return {"sales_order": so.name, "currency": so.currency, "rows": rows}


def create(opportunity, rows, expected_date, notes=None):
    opp = frappe.get_doc("Opportunity", opportunity)
    opp.check_permission("write")
    if opp.sales_stage != APPROVED_STAGE:
        frappe.throw(_("Invoices are requested once Accounts approve the project"))
    if not opp.custom_sales_order:
        frappe.throw(_("The deal has no Sales Order yet"))
    if not expected_date:
        frappe.throw(_("Set the expected invoice date"))
    rows = json.loads(rows or "[]") if isinstance(rows, str) else rows
    wanted = {}
    for r in rows or []:
        if flt(r.get("qty")) > 0:
            wanted[r.get("so_detail")] = flt(r.get("qty"))
    if not wanted:
        frappe.throw(_("Choose at least one item and its quantity"))
    so = frappe.get_doc("Sales Order", opp.custom_sales_order)
    br = frappe.new_doc("Billing Request")
    br.opportunity = opportunity
    br.sales_order = so.name
    br.expected_date = expected_date
    br.notes = notes
    br.billing_stage = TO_INVOICE
    for i in so.items:
        if i.name in wanted:
            br.append("items", {"so_detail": i.name, "item_code": i.item_code, "qty": wanted[i.name]})
    br.insert()
    return br.name


# ---------------------------------------------------------------- Billing Request events

def fill(doc):
    """Customer, company, currency and each line's item, service type and rate come from the Sales Order."""
    if not doc.sales_order and doc.opportunity:
        doc.sales_order = frappe.db.get_value("Opportunity", doc.opportunity, "custom_sales_order")
    if not doc.sales_order:
        frappe.throw(_("The deal has no Sales Order yet"))
    so = frappe.get_doc("Sales Order", doc.sales_order)
    doc.customer = so.customer
    doc.customer_name = so.customer_name
    doc.company = so.company
    doc.currency = so.currency
    lines = {}
    for i in so.items:
        lines[i.name] = i
    total = 0
    for r in doc.items:
        line = lines.get(r.so_detail)
        if not line:
            frappe.throw(fmt("Row {0}: this item isn't on Sales Order {1}", [r.idx, so.name]))
        r.item_code = line.item_code
        r.item_name = line.item_name
        r.description = frappe.utils.strip_html(line.description or "")[:500]
        r.service_type = line.get("custom_service_type")
        r.rate = flt(line.rate)
        r.amount = flt(r.qty) * r.rate
        total = total + r.amount
        if flt(r.qty) <= 0:
            frappe.throw(fmt("Row {0}: the quantity must be more than zero", [r.idx]))
        left = flt(line.qty) - billed_qty(line.name, None if doc.is_new() else doc.name)
        if flt(r.qty) > left + 0.0001:
            frappe.throw(fmt("Row {0}: only {1} of {2} is left to bill", [r.idx, left, line.item_name]))
    doc.total = total


def lines_signature(rows):
    return [[r.so_detail, flt(r.qty)] for r in rows]


def gate(doc, old, new):
    """What blocks a stage change: None, or the message."""
    if old == new:
        return None
    oi = STAGES.index(old) if old in STAGES else -1
    ni = STAGES.index(new) if new in STAGES else -1
    if ni < 0:
        return fmt("{0} isn't a billing stage", [new])
    if ni < oi:
        return None if is_finance() else _("Only Finance moves a billing request back")
    if ni > oi + 1 and not is_system():
        return fmt("Move it one stage at a time: next is {0}", [_(STAGES[oi + 1])])
    if new == TO_FINANCE and not doc.expected_date:
        return _("Set the expected invoice date first")
    if new == INVOICED:
        if not is_finance():
            return _("Finance marks the invoice as issued")
        if not (doc.invoice_number and doc.invoice_date):
            return _("Enter the invoice number and date first")
    if new == COLLECTED:
        if not is_finance():
            return _("Finance marks the invoice as collected")
        if not doc.collected_on:
            return _("Enter the date it was collected first")
    return None


def br_validate(doc):
    before = None if doc.is_new() else doc.get_doc_before_save()
    if doc.is_new():
        doc.billing_stage = doc.billing_stage or TO_INVOICE
        if doc.billing_stage != TO_INVOICE and not is_system():
            frappe.throw(_("A new billing request starts at To be invoiced"))
        opp = frappe.db.get_value("Opportunity", doc.opportunity, ["sales_stage", "custom_sales_order"], as_dict=True)
        if not opp or opp.sales_stage != APPROVED_STAGE:
            frappe.throw(_("Invoices are requested once Accounts approve the project"))
    elif before and before.billing_stage != TO_INVOICE and lines_signature(before.items) != lines_signature(doc.items) and not is_system():
        frappe.throw(_("The items are locked once the request went to Finance"))
    fill(doc)
    if doc.billing_stage == COLLECTED and not flt(doc.collected_amount):
        doc.collected_amount = doc.total
    if not doc.flags.eye_stage and before:
        error = gate(doc, before.billing_stage, doc.billing_stage)
        if error:
            frappe.throw(error, title=fmt("Can't move to {0}", [_(doc.billing_stage)]))


def br_on_update(doc):
    if doc.has_value_changed("billing_stage"):
        if doc.billing_stage == TO_FINANCE:
            frappe.db.set_value("Billing Request", doc.name, "sent_on", frappe.utils.now(), update_modified=False)
            assign("Billing Request", doc.name, finance_users(),
                   fmt("Issue the invoice for {0}: {1}", [doc.customer_name, money(doc.total, doc.currency)]), doc.expected_date)
            frappe.call("eye.books", op="send_invoice_request", name=doc.name)
        elif doc.billing_stage in DONE:
            close_todos("Billing Request", doc.name)
            owner = frappe.db.get_value("Opportunity", doc.opportunity, "owner")
            notify(owner, "Billing Request", doc.name, fmt("{0}: {1}", [doc.customer_name, _(doc.billing_stage)]))
    rollup(doc.opportunity)


def br_on_trash(doc):
    if doc.billing_stage != TO_INVOICE and not has_role("System Manager"):
        frappe.throw(_("Only a request still To be invoiced can be deleted"))
    for t in frappe.get_all("ToDo", filters={"reference_type": "Billing Request", "reference_name": doc.name}, pluck="name"):
        frappe.delete_doc("ToDo", t, ignore_permissions=True, force=True)
    rollup(doc.opportunity, exclude=doc.name)


def rollup(opportunity, exclude=None):
    """The deal's invoiced and collected amounts."""
    filters = {"opportunity": opportunity}
    if exclude:
        filters["name"] = ["!=", exclude]
    billed = 0
    collected = 0
    for r in frappe.get_all("Billing Request", filters=filters, fields=["billing_stage", "total", "collected_amount"]):
        if r.billing_stage in DONE:
            billed = billed + flt(r.total)
        collected = collected + flt(r.collected_amount)
    frappe.db.set_value("Opportunity", opportunity, {"custom_billed_amount": billed, "custom_collected_amount": collected},
                        update_modified=False)


# ---------------------------------------------------------------- Finance (by hand, or from eye.books)

def set_stage(br, stage, values):
    br.update(values)
    br.billing_stage = stage
    br.flags.ignore_permissions = True
    br.save()
    return {"stage": br.billing_stage}


def mark_invoiced(name, invoice_number, invoice_date, zoho_invoice_id=None):
    if not is_finance():
        frappe.throw(_("Finance marks the invoice as issued"))
    if not text(invoice_number) or not invoice_date:
        frappe.throw(_("Enter the invoice number and date"))
    br = frappe.get_doc("Billing Request", name)
    if br.billing_stage not in [TO_FINANCE, INVOICED]:
        frappe.throw(fmt("{0} is {1}, not waiting for Finance", [name, _(br.billing_stage)]))
    values = {"invoice_number": text(invoice_number), "invoice_date": invoice_date}
    if zoho_invoice_id:
        values["zoho_invoice_id"] = zoho_invoice_id
    return set_stage(br, INVOICED, values)


def mark_collected(name, collected_on, amount=None):
    if not is_finance():
        frappe.throw(_("Finance marks the invoice as collected"))
    if not collected_on:
        frappe.throw(_("Enter the date it was collected"))
    br = frappe.get_doc("Billing Request", name)
    if br.billing_stage not in [INVOICED, COLLECTED]:
        frappe.throw(fmt("{0} is {1}: mark it Invoiced first", [name, _(br.billing_stage)]))
    return set_stage(br, COLLECTED, {"collected_on": collected_on, "collected_amount": flt(amount) or br.total})


def record_payment(name, amount, collected_on=None):
    """Part of the invoice is paid (from eye.books): the amount, without changing the stage."""
    if not is_finance():
        frappe.throw(_("Not permitted"))
    br = frappe.get_doc("Billing Request", name)
    frappe.db.set_value("Billing Request", name, {"collected_amount": flt(amount), "collected_on": collected_on}, update_modified=False)
    rollup(br.opportunity)


# ---------------------------------------------------------------- reads for the desk

def steps(br):
    s = []
    s.append({"stage": TO_FINANCE, "key": "ready", "label": _("Items and expected invoice date"),
              "done": len(br.items) > 0 and bool(br.expected_date), "action": "form", "action_label": _("Open"), "waiting_on": None})
    s.append({"stage": INVOICED, "key": "invoice", "label": _("Finance issued the invoice"),
              "done": bool(br.invoice_number), "action": "invoice", "action_label": _("Mark Invoiced"),
              "waiting_on": _("Finance") if br.billing_stage == TO_FINANCE else None})
    s.append({"stage": COLLECTED, "key": "paid", "label": _("The client paid"),
              "done": bool(br.collected_on), "action": "collected", "action_label": _("Mark Collected"),
              "waiting_on": _("Finance") if br.billing_stage == INVOICED else None})
    return s


def flow_steps(name):
    return {"field": "billing_stage", "stages": STAGES, "steps": steps(get_br(name))}


def stage_check(name, to):
    br = get_br(name)
    error = gate(br, br.billing_stage, to)
    missing = [x for x in steps(br) if x["stage"] == to and not x["done"]] if not error else []
    return {"error": error, "missing": missing, "finance": is_finance()}


DOC_OPS = {
    "br_validate": br_validate,
    "br_on_update": br_on_update,
    "br_on_trash": br_on_trash,
}


def run(op, f):
    if op == "so_lines":
        return so_lines(f.opportunity)
    if op == "create":
        return create(f.opportunity, f.rows, f.expected_date, f.notes)
    if op == "mark_invoiced":
        return mark_invoiced(f.name, f.invoice_number, f.invoice_date, f.zoho_invoice_id if has_role("System Manager") else None)
    if op == "mark_collected":
        return mark_collected(f.name, f.collected_on, f.amount)
    if op == "record_payment":
        return record_payment(f.name, f.amount, f.collected_on)
    if op == "flow_steps":
        return flow_steps(f.name)
    if op == "stage_check":
        return stage_check(f.name, f.to)
    frappe.throw(fmt("Unknown billing action: {0}", [op]))


op = form.get("op")
if op in DOC_OPS:
    target = form.get("doc")
    if target is None or isinstance(target, (str, bytes, dict, list)):
        frappe.throw(_("Not permitted"))
    DOC_OPS[op](target)
else:
    frappe.flags.result = run(op, form)

# Eye CRM accounting adapter: the deal and billing cycle lives in ERPNext, and this script
# carries it to the accounting system. The mode is in Eye Books Settings:
#
#   Manual  nothing is sent; Accounts approve and Finance records invoices with buttons.
#   Zoho    quotes go to Zoho Books as Estimates, invoice requests as Sales Orders; approvals,
#           invoices and payments come back from Zoho (a 5-minute job, nudged by a webhook).
#
#   desk:     frappe.call({method: "eye.books", args: {op: "test"}}) -> r.message.result
#   scripts:  frappe.call("eye.books", op="send_quote", name=opportunity)
#
# Every call to Zoho is written to Eye Sync Log; a failed one can be retried from there.

ACCOUNTS_STAGE = "Accounts, please approve"
TO_FINANCE = "Finance, please issue"
INVOICED = "Invoiced"
SETTINGS = "Eye Books Settings"

flt = frappe.utils.flt
form = frappe.form_dict


# ---------------------------------------------------------------- helpers

def fmt(msg, values):
    out = _(msg)
    for i, v in enumerate(values):
        out = out.replace("{" + str(i) + "}", str(v))
    return out


def text(v):
    return " ".join(str(v or "").split())


def has_role(role):
    user = frappe.session.user
    if user == "Administrator":
        return True
    return bool(frappe.db.exists("Has Role", {"parent": user, "parenttype": "User", "role": role}))


def require_manager():
    if not (has_role("System Manager") or has_role("Accounts Manager")):
        frappe.throw(_("Only an Accounts Manager can do this"))


def settings():
    return frappe.get_doc(SETTINGS, SETTINGS)


def mode():
    return frappe.db.get_single_value(SETTINGS, "mode") or "Manual"


def log(operation, doctype, name, ok, request=None, response=None, error=None):
    frappe.get_doc({"doctype": "Eye Sync Log", "operation": operation, "reference_doctype": doctype,
                    "reference_name": name, "status": "Success" if ok else "Error",
                    "request": json.dumps(request, indent=1, default=str) if request else None,
                    "response": json.dumps(response, indent=1, default=str)[:20000] if response else None,
                    "error": text(error)[:1000] if error else None}).insert(ignore_permissions=True)


# ---------------------------------------------------------------- Zoho Books

def token():
    s = settings()
    if s.access_token and s.token_expires and str(s.token_expires) > str(frappe.utils.add_to_date(frappe.utils.now_datetime(), minutes=2)):
        return s.get_password("access_token")
    accounts = (s.accounts_domain or "https://accounts.zoho.com").rstrip("/")
    out = frappe.make_post_request(accounts + "/oauth/v2/token", params={
        "refresh_token": s.get_password("refresh_token"), "client_id": s.client_id,
        "client_secret": s.get_password("client_secret"), "grant_type": "refresh_token"})
    if not out or not out.get("access_token"):
        frappe.throw(fmt("Zoho didn't give an access token: {0}", [text((out or {}).get("error") or out)]))
    s = settings()
    s.access_token = out.get("access_token")
    s.token_expires = frappe.utils.add_to_date(frappe.utils.now_datetime(), seconds=int(out.get("expires_in") or 3600))
    s.flags.ignore_permissions = True
    s.flags.ignore_mandatory = True
    s.save()
    return out.get("access_token")


def zoho_error(e):
    # the HTTP status and URL (no token: it travels in a header); Zoho's full answer is in the Error Log
    return text(str(e))[:500]


def zoho(method, path, params=None, body=None):
    s = settings()
    url = (s.api_domain or "https://www.zohoapis.com").rstrip("/") + "/books/v3" + path
    query = {"organization_id": s.organization_id}
    query.update(params or {})
    headers = {"Authorization": "Zoho-oauthtoken " + token(), "Content-Type": "application/json"}
    try:
        if method == "GET":
            out = frappe.make_get_request(url, params=query, headers=headers)
        elif method == "PUT":
            out = frappe.make_put_request(url, params=query, headers=headers, json=body)
        else:
            out = frappe.make_post_request(url, params=query, headers=headers, json=body)
    except Exception as e:
        frappe.throw(zoho_error(e), title=_("Zoho Books"))
    if isinstance(out, dict) and out.get("code") not in (None, 0):
        frappe.throw(str(out.get("code")) + ": " + text(out.get("message")), title=_("Zoho Books"))
    return out or {}


def custom_fields(pairs):
    return [{"api_name": k, "value": v} for k, v in pairs if k and v]


def zoho_customer(customer):
    """The customer's Zoho contact id; a customer made in ERPNext is created in Zoho once."""
    c = frappe.get_doc("Customer", customer)
    if c.custom_zoho_contact_id:
        return c.custom_zoho_contact_id
    out = zoho("POST", "/contacts", body={"contact_name": c.customer_name, "company_name": c.customer_name,
                                           "contact_type": "customer"})
    contact_id = out.get("contact", {}).get("contact_id")
    frappe.db.set_value("Customer", customer, "custom_zoho_contact_id", contact_id, update_modified=False)
    log("Create customer", "Customer", customer, True, {"contact_name": c.customer_name}, out.get("contact"))
    return contact_id


def zoho_lines(rows):
    out = []
    for r in rows:
        item_id = frappe.db.get_value("Item", r.item_code, "custom_zoho_item_id")
        if not item_id:
            frappe.throw(fmt("Item {0} isn't linked to Zoho Books: sync the items from Zoho, then try again", [r.item_code]))
        out.append({"item_id": item_id, "description": text(frappe.utils.strip_html(r.description or ""))[:2000],
                    "quantity": flt(r.qty), "rate": flt(r.rate)})
    return out


# ---------------------------------------------------------------- quote -> Estimate (approval)

def send_quote(name):
    """The deal entered "Accounts, please approve": its quote goes to the accounting system."""
    if mode() != "Zoho":
        return "manual"
    try:
        return push_estimate(name)
    except Exception as e:
        log("Send quote", "Opportunity", name, False, error=str(e))
        frappe.get_doc("Opportunity", name).add_comment(
            "Comment", fmt("The quote didn't reach Zoho Books: {0}. Retry it from Eye Sync Log.", [text(str(e))[:300]]))
        return "error"


def push_estimate(name):
    opp = frappe.get_doc("Opportunity", name)
    rows = frappe.get_all("Quotation", filters={"opportunity": name, "docstatus": ["<", 2]}, pluck="name",
                          order_by="modified desc", limit=1)
    if not rows:
        frappe.throw(_("The deal has no quotation"))
    q = frappe.get_doc("Quotation", rows[0])
    if q.quotation_to != "Customer":
        frappe.throw(_("The quotation is for a lead: make it a customer first"))
    s = settings()
    body = {"customer_id": zoho_customer(q.party_name), "reference_number": name, "date": str(q.transaction_date),
            "line_items": zoho_lines(q.items),
            "custom_fields": custom_fields([(s.deal_field, name)])}
    out = zoho("POST", "/estimates", body=body)
    est = out.get("estimate") or {}
    zoho("POST", "/estimates/" + est.get("estimate_id") + "/status/sent")
    frappe.db.set_value("Opportunity", name, "custom_zoho_estimate_id", est.get("estimate_id"), update_modified=False)
    opp.add_comment("Info", fmt("Sent to Zoho Books as Estimate {0}", [est.get("estimate_number")]))
    log("Send quote", "Opportunity", name, True, body, est)
    return est.get("estimate_id")


def check_quotes():
    """Deals waiting for Accounts: an accepted Estimate approves, a declined one sends it back."""
    done = 0
    for d in frappe.get_all("Opportunity", filters={"sales_stage": ACCOUNTS_STAGE, "custom_zoho_estimate_id": ["is", "set"]},
                            fields=["name", "custom_zoho_estimate_id"]):
        try:
            est = zoho("GET", "/estimates/" + d.custom_zoho_estimate_id).get("estimate") or {}
            status = est.get("status")
            if status in ("accepted", "invoiced"):
                frappe.call("eye.pricing", op="approve_project", name=d.name, note=_("Approved in Zoho Books"))
                log("Approval", "Opportunity", d.name, True, response={"status": status})
                done = done + 1
            elif status == "declined":
                reason = text(est.get("notes")) or _("Declined in Zoho Books")
                frappe.call("eye.pricing", op="reject_project", name=d.name, reason=reason)
                log("Approval", "Opportunity", d.name, True, response={"status": status})
                done = done + 1
        except Exception as e:
            log("Approval", "Opportunity", d.name, False, error=str(e))
    return done


# ---------------------------------------------------------------- invoice request -> Sales Order

def send_invoice_request(name):
    """The request entered "Finance, please issue": it goes to the accounting system."""
    if mode() != "Zoho":
        return "manual"
    try:
        return push_sales_order(name)
    except Exception as e:
        log("Send invoice request", "Billing Request", name, False, error=str(e))
        frappe.get_doc("Billing Request", name).add_comment(
            "Comment", fmt("The request didn't reach Zoho Books: {0}. Retry it from Eye Sync Log.", [text(str(e))[:300]]))
        return "error"


def push_sales_order(name):
    br = frappe.get_doc("Billing Request", name)
    s = settings()
    body = {"customer_id": zoho_customer(br.customer), "reference_number": name, "date": frappe.utils.nowdate(),
            "shipment_date": str(br.expected_date), "line_items": zoho_lines(br.items), "notes": text(br.notes) or None,
            "custom_fields": custom_fields([(s.deal_field, br.opportunity), (s.billing_field, name)])}
    out = zoho("POST", "/salesorders", body=body)
    so = out.get("salesorder") or {}
    zoho("POST", "/salesorders/" + so.get("salesorder_id") + "/status/open")
    frappe.db.set_value("Billing Request", name, "zoho_salesorder_id", so.get("salesorder_id"), update_modified=False)
    br.add_comment("Info", fmt("Sent to Zoho Books as Sales Order {0}", [so.get("salesorder_number")]))
    log("Send invoice request", "Billing Request", name, True, body, so)
    return so.get("salesorder_id")


def check_invoices():
    """Requests with Finance: the invoice made from the Zoho Sales Order, then its payments."""
    done = 0
    for r in frappe.get_all("Billing Request", filters={"billing_stage": TO_FINANCE, "zoho_salesorder_id": ["is", "set"]},
                            fields=["name", "zoho_salesorder_id"]):
        try:
            so = zoho("GET", "/salesorders/" + r.zoho_salesorder_id).get("salesorder") or {}
            invoices = [i for i in so.get("invoices") or [] if i.get("status") not in ("void", "draft")]
            if invoices:
                inv = invoices[0]
                frappe.call("eye.billing", op="mark_invoiced", name=r.name, invoice_number=inv.get("invoice_number"),
                            invoice_date=inv.get("date"), zoho_invoice_id=inv.get("invoice_id"))
                log("Invoice", "Billing Request", r.name, True, response=inv)
                done = done + 1
        except Exception as e:
            log("Invoice", "Billing Request", r.name, False, error=str(e))
    for r in frappe.get_all("Billing Request", filters={"billing_stage": INVOICED, "zoho_invoice_id": ["is", "set"]},
                            fields=["name", "zoho_invoice_id", "collected_amount"]):
        try:
            inv = zoho("GET", "/invoices/" + r.zoho_invoice_id).get("invoice") or {}
            paid = flt(inv.get("total")) - flt(inv.get("balance"))
            when = inv.get("last_payment_date") or frappe.utils.nowdate()
            if inv.get("status") == "paid":
                frappe.call("eye.billing", op="mark_collected", name=r.name, collected_on=when, amount=paid)
                log("Payment", "Billing Request", r.name, True, response={"status": "paid", "paid": paid})
                done = done + 1
            elif paid > flt(r.collected_amount):
                frappe.call("eye.billing", op="record_payment", name=r.name, amount=paid, collected_on=when)
                log("Payment", "Billing Request", r.name, True, response={"status": inv.get("status"), "paid": paid})
        except Exception as e:
            log("Payment", "Billing Request", r.name, False, error=str(e))
    return done


# ---------------------------------------------------------------- customers and items from Zoho

def pages(path, key):
    rows = []
    page = 1
    while page < 200:
        out = zoho("GET", path, params={"page": page, "per_page": 200})
        rows = rows + (out.get(key) or [])
        if not (out.get("page_context") or {}).get("has_more_page"):
            break
        page = page + 1
    return rows


def default(doctype, preferred):
    if preferred and frappe.db.exists(doctype, preferred):
        return preferred
    rows = frappe.get_all(doctype, filters={"is_group": 0} if doctype in ("Customer Group", "Territory", "Item Group") else {},
                          pluck="name", limit=1)
    return rows[0] if rows else None


def sync_customers():
    group = default("Customer Group", frappe.db.get_single_value("Selling Settings", "customer_group"))
    territory = default("Territory", frappe.db.get_single_value("Selling Settings", "territory"))
    made = 0
    linked = 0
    for c in pages("/contacts?contact_type=customer", "contacts"):
        cid = c.get("contact_id")
        if frappe.db.exists("Customer", {"custom_zoho_contact_id": cid}):
            continue
        name = text(c.get("contact_name"))
        existing = frappe.db.get_value("Customer", {"customer_name": name})
        if existing:
            frappe.db.set_value("Customer", existing, "custom_zoho_contact_id", cid, update_modified=False)
            linked = linked + 1
            continue
        frappe.get_doc({"doctype": "Customer", "customer_name": name, "customer_type": "Company",
                        "customer_group": group, "territory": territory,
                        "custom_zoho_contact_id": cid}).insert(ignore_permissions=True)
        made = made + 1
    return {"customers_new": made, "customers_linked": linked}


def service_type_of(item, field, missing):
    """The item's service type from its Zoho field. Only Eye's own Service Types are used (each
    has a Deal Nature); a value Eye doesn't have is reported, and the item is left without one."""
    if not field:
        return None
    value = item.get(field)
    for cf in item.get("custom_fields") or []:
        if cf.get("api_name") == field:
            value = cf.get("value")
    value = text(value)
    if not value:
        return None
    found = frappe.db.get_value("Service Type", value)
    if not found:
        if value not in missing:
            missing.append(value)
        return None
    return found


def sync_items():
    s = settings()
    group = default("Item Group", s.default_item_group)
    uom = "Nos" if frappe.db.exists("UOM", "Nos") else default("UOM", None)
    made = 0
    linked = 0
    missing = []
    for it in pages("/items", "items"):
        iid = it.get("item_id")
        stype = service_type_of(it, s.item_service_type_field, missing)
        found = frappe.db.get_value("Item", {"custom_zoho_item_id": iid})
        if found:
            if stype and not frappe.db.get_value("Item", found, "custom_service_type"):
                frappe.db.set_value("Item", found, "custom_service_type", stype, update_modified=False)
            continue
        code = text(it.get("sku")) or text(it.get("name"))
        existing = frappe.db.get_value("Item", code) or frappe.db.get_value("Item", {"item_name": text(it.get("name"))})
        if existing:
            values = {"custom_zoho_item_id": iid}
            if stype and not frappe.db.get_value("Item", existing, "custom_service_type"):
                values["custom_service_type"] = stype
            frappe.db.set_value("Item", existing, values, update_modified=False)
            linked = linked + 1
            continue
        frappe.get_doc({"doctype": "Item", "item_code": code[:140], "item_name": text(it.get("name"))[:140],
                        "item_group": group, "stock_uom": uom, "is_stock_item": 0, "include_item_in_manufacturing": 0,
                        "description": text(it.get("description")) or text(it.get("name")),
                        "standard_rate": flt(it.get("rate")), "custom_service_type": stype,
                        "custom_zoho_item_id": iid}).insert(ignore_permissions=True)
        made = made + 1
    out = {"items_new": made, "items_linked": linked}
    if missing:
        out["service_types_not_in_eye"] = missing
    return out


def sync_masters():
    out = {}
    try:
        out.update(sync_customers())
        out.update(sync_items())
        log("Sync customers and items", None, None, True, response=out)
    except Exception as e:
        log("Sync customers and items", None, None, False, error=str(e))
        frappe.throw(str(e))
    frappe.db.set_value(SETTINGS, SETTINGS, "last_sync", frappe.utils.now())
    return out


# ---------------------------------------------------------------- runs

def check_all():
    out = {"answers": check_quotes(), "invoices": check_invoices()}
    frappe.db.set_value(SETTINGS, SETTINGS, {"last_check": frappe.utils.now(), "check_requested": 0})
    return out


def tick():
    """Every 5 minutes (Scheduler Event). Calls Zoho only when the webhook asked, once an hour,
    and syncs customers and items once a day."""
    if mode() != "Zoho":
        return "manual"
    s = settings()
    now = frappe.utils.now_datetime()
    out = {}
    hour_ago = str(frappe.utils.add_to_date(now, hours=-1))
    if s.check_requested or not s.last_check or str(s.last_check) < hour_ago:
        out.update(check_all())
    day_ago = str(frappe.utils.add_to_date(now, days=-1))
    if not s.last_sync or str(s.last_sync) < day_ago:
        try:
            out.update(sync_masters())
        except Exception:
            pass
    return out


def retry(log_name):
    require_manager()
    entry = frappe.get_doc("Eye Sync Log", log_name)
    if entry.operation == "Send quote":
        result = push_estimate(entry.reference_name)
    elif entry.operation == "Send invoice request":
        result = push_sales_order(entry.reference_name)
    elif entry.operation == "Sync customers and items":
        result = sync_masters()
    else:
        result = check_all()
    frappe.db.set_value("Eye Sync Log", log_name, "attempts", (entry.attempts or 1) + 1)
    return result


def test():
    require_manager()
    if mode() != "Zoho":
        frappe.throw(_("Set the Accounting System to Zoho first"))
    out = zoho("GET", "/organizations")
    s = settings()
    org = [o for o in out.get("organizations") or [] if str(o.get("organization_id")) == str(s.organization_id)]
    if not org:
        frappe.throw(fmt("Connected, but organization {0} isn't in this Zoho account", [s.organization_id]))
    return {"organization": org[0].get("name"), "currency": org[0].get("currency_code")}


def run(op, f):
    if op == "send_quote":
        return send_quote(f.name)
    if op == "send_invoice_request":
        return send_invoice_request(f.name)
    if op == "tick":
        require_manager()
        return tick()
    if op == "check_now":
        require_manager()
        return check_all()
    if op == "sync_now":
        require_manager()
        return sync_masters()
    if op == "retry":
        return retry(f.log)
    if op == "test":
        return test()
    if op == "mode":
        return mode()
    frappe.throw(fmt("Unknown accounting action: {0}", [op]))


frappe.flags.result = run(form.get("op"), form)

# The Flow Steps Method for Nexlify Board (set in Nexlify Board Settings): every stage's steps
# for a deal or a billing request. Eye works without Nexlify Board; this only feeds its screen.
dt = frappe.form_dict.get("doctype")
name = frappe.form_dict.get("name")
if dt == "Opportunity":
    frappe.flags.result = frappe.call("eye.pricing", op="flow_steps", name=name).get("result")
elif dt == "Billing Request":
    frappe.flags.result = frappe.call("eye.billing", op="flow_steps", name=name).get("result")
else:
    frappe.flags.result = {}
